head.script:
scwin.screenId = "jldfil35604";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((String(String(dma_disclosureSchedule.get("calndDd")) == null ? '' : String(dma_disclosureSchedule.get("calndDd"))) === '' ? '' : String("yyyy-MM-dd").replace(/yyyy/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(0,4)).replace(/MM/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(4,6)).replace(/dd/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(6,8)).replace(/HH/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(8,10)).replace(/mm/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(10,12)).replace(/ss/g, String(String(dma_disclosureSchedule.get("calndDd"))).slice(12,14)))); } },
        { childId: "btn_Disclsviewer", fn: function () { return String(dma_disclosureSchedule.get("schdlContn")); } },
        { childId: "__rb2", fn: function () { return String((String(String(dma_disclosureSchedule.get("preCalndDd")) == null ? '' : String(dma_disclosureSchedule.get("preCalndDd"))) === '' ? '' : String("yyyy-MM-dd hh:mm").replace(/yyyy/g, String(String(dma_disclosureSchedule.get("preCalndDd"))).slice(0,4)).replace(/MM/g, String(String(dma_disclosureSchedule.get("preCalndDd"))).slice(4,6)).replace(/dd/g, String(String(dma_disclosureSchedule.get("preCalndDd"))).slice(6,8)).replace(/HH/g, String(String(dma_disclosureSchedule.get("preCalndDd"))).slice(8,10)).replace(/mm/g, String(String(dma_disclosureSchedule.get("preCalndDd"))).slice(10,12)).replace(/ss/g, String(String(dma_disclosureSchedule.get("preCalndDd"))).slice(12,14)))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35604.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Disclsviewer_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Disclsviewer_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Disclsviewer_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.disclsviewer('' + dma_disclosureSchedule.get("acptNo") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35604.btn_Disclsviewer_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35604.btn_Close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.disclsviewer
 * @author Inswave
 * @date 2026. 09. 29
 * @param _acptNo
 * @returns
 * @hidden N
*/
scwin.disclsviewer = function (_acptNo) {
    /* sdd-asis-lifecycle:begin fn_Disclsviewer — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const viewerUrl = "/submission/disclosureView.do?acptNo=" + _acptNo;
    $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(viewerUrl), { id: "viewer", scrollbars: true, resizable: false, width: "1020", height: "700", type: "pageFramePopup" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_Close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
